import axios from 'axios';

// Set your backend's base URL
const API_BASE_URL = 'http://<your-server-ip>:3000'; // Replace <your-server-ip> with your machine's IP address

const api = axios.create({
  baseURL: API_BASE_URL,
});

export default api;
